def calculate_weighted_scores(df, student_focus):
    student_ids = df.index.tolist()
    scores = df.lookup(student_ids, student_focus)
    weights = np.array([0.7, 0.2, 0.1])
    results = []
    for i in range(len(student_ids)):
        row_vals = df.loc[student_ids[i]].values.astype(float)
        weighted_sum = np.sum(row_vals * weights)
        results.append(weighted_sum - scores[i])
    return pd.Series(results, index=student_ids, name='variance')

