def gen(rng):
    n = rng.randint(5, 12)
    sensors = ['s1', 's2', 's3']
    data = {'baseline': [round(rng.uniform(10, 20), 3) for _ in range(n)]}
    for s in sensors:
        data[s] = [round(rng.uniform(10, 20), 3) for _ in range(n)]

    target_sensors = [rng.choice(sensors) for _ in range(n)]

    # Ensure at least one drift is actually triggered for realism
    idx = rng.randint(0, n-1)
    s_name = target_sensors[idx]
    data[s_name][idx] = data['baseline'][idx] + 0.1

    return {
        "df": {"__df__": data},
        "target_sensors": target_sensors
    }

